def _get_pooling_layers(self, start_node_id, end_node_id):
        """Given two node IDs, return all the pooling layers between them."""
        pooling_layers = []
        start_node = self.nodes[start_node_id]
        end_node = self.nodes[end_node_id]
        for node_id in range(start_node_id, end_node_id):
            node = self.nodes[node_id]
            if isinstance(node, PoolingLayer):
                if node.in_node == start_node or node.in_node == end_node:
                    pooling_layers.append(node)
                    start_node = node
        return pooling_layers

